{
  "selections": [
    {
      "trait_id": "/core_belief/young_schema",
      "background_ids": ["/childhood_data", "/situations/3"],
      "relevance": "내담자가 '사람들 앞에서 잘못했던 장면'을 반복 회상하며, 상담사가 '창피함'을 감정으로 추정함. 이는 결함/수치심 스키마가 작동하는 전형적 상황으로, 어린 시절 실수나 힘든 모습을 감추도록 요구받은 경험(성장 배경)과, 밤에 과거 실수 장면이 떠올라 수치심을 느끼는 상황 사례와 직접 연결됨."
    },
    {
      "trait_id": "/core_belief/core_belief_statement",
      "background_ids": ["/situations/3"],
      "relevance": "과거 실수 장면이 자꾸 떠오르는 것은 '사람들이 진짜 나를 알면 결국 떠날 것'이라는 핵심 신념이 활성화된 상태. 상황 사례에서 '그때 그 모습이 진짜 나였어. 사람들이 그 모습을 다 봤다면 지금처럼 나를 대하지 않았을 거야'라는 자동사고가 동일한 신념을 반영함."
    },
    {
      "trait_id": "/intermediate_beliefs/attitude",
      "background_ids": ["/childhood_data"],
      "relevance": "내담자가 과거 사람들 앞에서 실수한 장면을 고통스럽게 회상하는 것은, 약점이나 부족한 모습이 드러나는 것을 끔찍하게 여기는 태도가 작동하고 있음을 보여줌. 어릴 적 실수나 힘든 모습을 '남들 앞에서 그러지 말라'며 감추도록 요구받은 경험이 이 태도의 기원."
    },
    {
      "trait_id": "/coping_strategies/1",
      "background_ids": ["/situations/3"],
      "relevance": "내담자가 낮에는 괜찮은 척하지만 밤에 혼자 과거 실수 장면을 떠올리며 잠을 못 자는 패턴은, 사람들 앞에서 항상 밝고 문제없는 모습을 유지하고 힘든 감정은 혼자 삭히는 대처 전략과 일치. 상황 사례에서 '다음 날은 평소보다 더 밝고 괜찮은 척 행동함'이 이를 뒷받침함."
    }
  ]
}

